package com.v7.quantumfast; import android.view.*; import android.widget.*; import androidx.annotation.NonNull; import androidx.recyclerview.widget.RecyclerView; import java.util.List;
public class AppAdapter extends RecyclerView.Adapter<AppAdapter.H>{ List<AppInfo> list; public AppAdapter(List<AppInfo> l){list=l;} static class H extends RecyclerView.ViewHolder{ ImageView icon; TextView name; H(View v){super(v);icon=v.findViewById(R.id.appIcon);name=v.findViewById(R.id.appName);} } @NonNull public H onCreateViewHolder(@NonNull ViewGroup p,int t){return new H(LayoutInflater.from(p.getContext()).inflate(R.layout.item_app,p,false));} public void onBindViewHolder(@NonNull H h,int i){AppInfo a=list.get(i);h.name.setText(a.name);h.icon.setImageDrawable(a.icon);h.itemView.setOnClickListener(v->{try{v.getContext().startActivity(v.getContext().getPackageManager().getLaunchIntentForPackage(a.pkg));}catch(Exception e){}});} public int getItemCount(){return list.size();} }
